// 1. On récupère TOUTES les itérations du nœud Get_categorie1
// La syntaxe .all() est la plus sûre pour récupérer tous les items d'une boucle
const allCategories = $("Get_categorie1").all();

// 2. Vos mots-clés (on les met en minuscule pour simplifier)
const targets = [
  "vtt", "route", "urbain", "trekking", "trekkin", 
  "route performance", "speed bike", "urbain/trekking", 
  "vtc/fitness", "vtc", "pliable/compact", "enfant", "bmx/dirt/trial"
];

let typeVelo = "Non défini";
let idVelo = null;
let nomsTrouves = []; // Pour vous aider à débugger

// 3. On boucle sur les catégories récupérées
for (const item of allCategories) {
  const name = item.json.name;
  if (!name) continue;

  nomsTrouves.push(name); // On stocke le nom pour le voir en sortie
  const categoryNameLower = name.toLowerCase();

  // On cherche si un de nos mots-clés est présent dans le nom de la catégorie
  const found = targets.find(t => categoryNameLower.includes(t.toLowerCase()));

  if (found) {
    typeVelo = name;
    idVelo = item.json.id;
    break; // On s'arrête au premier match trouvé
  }
}

// 4. On retourne le résultat
return {
  type_velo_final: typeVelo,
  id_categorie_principale: idVelo,
  debug_tous_les_noms_scannes: nomsTrouves.join(", ") // Utile pour voir ce que le code a lu
};









